package com.nthexperience.desktop;
import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.lang.reflect.*;
import java.util.*;
import org.json.*;

/** Regression through real Search tabs, Win+X popup, metadata, fonts, previews and feed cards. */
public final class TenReferenceSmoke extends TenThemeSmoke {
 @Override public void onStart(){Bundle result=new Bundle();try{
  store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).putBoolean("ten_full_start",false).putString("ten_font","selawik").commit();Aero.resetFont();TenThemes.TEN.get(0).apply(store);
  getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
  home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.description(root,"Start menu")!=null,"Shell ready");
  for(int orientation:new int[]{ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE}){boolean portrait=orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT;ui(()->home.setRequestedOrientation(orientation));await(()->portrait?root.getHeight()>root.getWidth():root.getWidth()>root.getHeight(),"Orientation ready");String suffix=portrait?"portrait":"landscape";
   ui(()->{home.open("@notes");home.open("@search");StartMenu search=TenSmoke.find(root,StartMenu.class);check(search.searchMode&&search.landing.isShown(),"Search opens its own landing page");check(TenSmoke.text(search,"Recent")!=null&&TenSmoke.text(search,"Top apps")!=null&&TenSmoke.text(search,"Quick searches")!=null,"Reference search sections");});shot("ten10-search-"+suffix);
   ui(()->{StartMenu search=TenSmoke.find(root,StartMenu.class);TenSmoke.description(search,"Search tab Apps").performClick();search.search.setText("Calculator");check(TenSmoke.description(search.appList,"Open Calculator")!=null,"Apps tab filters real results");TenSmoke.description(search,"Search tab Documents").performClick();check(TenSmoke.description(search.appList,"Open Calculator")==null,"Documents tab excludes apps");home.open("ten-setting:about");TenSettings settings=(TenSettings)windows().get("@settings").body;check(TenSmoke.text(settings,"Installed RAM")!=null&&TenSmoke.text(settings,"Processor")!=null&&TenSmoke.text(settings,"Storage")!=null,"Hardware summary cards");check(TenSmoke.text(settings,Build.MODEL)!=null||TenSmoke.text(settings,Build.MANUFACTURER+" "+Build.MODEL)!=null,"Actual device metadata");View copy=TenSmoke.description(settings,"Copy Device specifications");check(copy!=null,"Copyable device details");copy.performClick();check(home.getSystemService(ClipboardManager.class).getPrimaryClip().getItemAt(0).getText().toString().contains(Build.MODEL),"Copy contains actual device specifications");});shot("ten10-about-"+suffix);
   ui(()->{home.open("ten-setting:fonts");TenFonts fonts=TenSmoke.find(root,TenFonts.class);check(fonts!=null&&TenSmoke.description(fonts,"Use font Monospace")!=null,"Font gallery and apply control");fonts.query.setText("Serif");check(TenSmoke.description(fonts,"Use font Monospace")==null,"Font search filters");fonts.query.setText("");fonts.sample.setText("My Nth desktop");check(TenSmoke.text(fonts,"My Nth desktop")!=null,"Editable preview text");});shot("ten10-fonts-"+suffix);
   ui(()->{TenFonts fonts=TenSmoke.find(root,TenFonts.class);TenSmoke.description(fonts,"Use font Monospace").performClick();check(store.prefs.getString("ten_font","").equals("monospace"),"Font saved");try{DesktopBackup.Plan plan=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check("monospace".equals(plan.values.get("ten_font")),"Font included in backup");}catch(Exception e){throw new RuntimeException(e);}store.prefs.edit().putString("ten_font","selawik").commit();Aero.resetFont();home.applyTenFont();home.open("@taskview");});await(()->TenSmoke.find(root,TenTaskView.Flow.class)!=null&&TenSmoke.find(root,TenTaskView.Flow.class).getWidth()>0,"Task thumbnails visible");ui(()->{TenTaskView.Flow flow=TenSmoke.find(root,TenTaskView.Flow.class);check(flow.getChildCount()>=2,"Real open windows have thumbnails");View overlay=TenSmoke.description(root,"Task View");check(overlay.getBackground() instanceof android.graphics.drawable.BitmapDrawable,"Wallpaper backdrop captured");Bitmap backdrop=((android.graphics.drawable.BitmapDrawable)overlay.getBackground()).getBitmap();for(int y=0;y<backdrop.getHeight();y+=Math.max(1,backdrop.getHeight()/9))for(int x=0;x<backdrop.getWidth();x+=Math.max(1,backdrop.getWidth()/9))check(Color.alpha(backdrop.getPixel(x,y))==255,"Task View cannot show underlying windows through its wallpaper");for(int i=0;i<flow.getChildCount();i++){View card=flow.getChildAt(i);check(card.getLeft()>=0&&card.getRight()<=flow.getWidth(),"Thumbnail inside screen");}});shot("ten10-tasks-"+suffix);
   ui(()->{home.open("@notes");home.dispatchKeyEvent(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_X,0,KeyEvent.META_META_ON));});awaitSystem("Event Viewer");awaitSystem("Windows PowerShell (Admin)");awaitSystem("Shut down or sign out");shot("ten10-winx-"+suffix);systemClick("Device Manager");await(()->windows().get("@devices")!=null,"Win+X Device Manager routes to real inventory");
   ui(()->{JSONArray stories=new JSONArray();for(int i=0;i<6;i++){JSONObject story=new JSONObject();GadgetLayout.put(story,"title","Reference layout fixture headline "+i);GadgetLayout.put(story,"url","https://example.org/story/"+i);GadgetLayout.put(story,"summary","A deterministic feed entry for layout verification.");stories.put(story);}store.prefs.edit().putString("feed_items",stories.toString()).putString("feed_url","").putBoolean("ten_news_images",false).commit();home.open("@news");});await(()->TenSmoke.description(root,"News story: Reference layout fixture headline 0")!=null,"Hero story rendered");ui(()->{check(TenSmoke.description(root,"Top stories summary")!=null,"Top stories group");check(TenSmoke.description(root,"News weather card")!=null,"Weather sidebar");check(TenSmoke.description(root,"Nth games card")!=null,"Game tiles");});shot("ten10-news-"+suffix);ui(()->TenSmoke.description(root,"Close news and interests").performClick());
  }
  ui(()->{for(String id:new String[]{"@events","@management","@powershell","@powershell-admin"})home.open(id);check(TenSmoke.description(root,"Nth PowerShell command")!=null,"Native command entry");try{Map<String,Object> invalid=new HashMap<>();invalid.put("ten_font","../../bad.ttf");boolean rejected=false;try{TenPreferences.validate(invalid);}catch(JSONException expected){rejected=true;}check(rejected,"Unknown backup font rejected");}catch(Exception e){throw new RuntimeException(e);}});
  result.putString("stream","PASS: reference Search landing and functional filters, hardware metadata/copy, searchable/customizable Fonts with persistent choice and backup, wallpaper Task View thumbnail bounds, complete Win+X and real Android destinations, hero/top stories/weather/game feed layout, portrait and landscape\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{shot("ten10-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
